/* MyRoad service worker (#234, decision 0015). Generated by ui/pwa.py.
   Only the public shell (/static + /offline) is ever cached. Runtime responses are never
   stored, so /api, /tools, /login*, signed-in pages and cookie-setting responses can't be. */
const CACHE = __CACHE__;
const PREFIX = __PREFIX__;
const OFFLINE = __OFFLINE__;
const PRECACHE = __PRECACHE__;

function cacheable(res) {
  if (!res || !res.ok || res.type !== "basic" || res.redirected) return false;
  const cc = (res.headers.get("Cache-Control") || "").toLowerCase();
  return !/private|no-store/.test(cc) && !res.headers.has("Set-Cookie");
}

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    for (const url of PRECACHE) {
      const res = await fetch(url, { cache: "reload", credentials: "omit" });
      if (!cacheable(res)) throw new Error("not cacheable: " + url);
      await cache.put(url, res);
    }
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith(PREFIX) && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (req.mode === "navigate") {
    // Network-only; the offline page only when the network fails. Nothing is stored.
    event.respondWith(fetch(req).catch(async () => (await caches.match(OFFLINE, { cacheName: CACHE })) || Response.error()));
    return;
  }
  if (PRECACHE.includes(url.pathname) && url.pathname.startsWith("/static/")) {
    event.respondWith((async () => (await caches.match(url.pathname, { cacheName: CACHE })) || fetch(req))());
  }
  // Everything else (/api, /tools, /login*, htmx fragments, ...) goes to the network untouched.
});
